data={'schemaVersion':1,'status':'CANDIDATE_ONLY','autoFollow':False,'source':{'id':'N01-03-v02','version':'v02','fileName':inventory['name'],'docxSha256':inventory['file_sha256'],'textSha256':inventory['text_sha256'],'archiveSha256':'f3269b9693521bbaf3563fd92fbd5da795d2c0a791d2eb5abafd1ccd3e5f2a84','registry':'https://app.notion.com/p/3dfc9e66576681a4ba9cc5b3be2934de','sourceText':'source-no01-03.txt'},'arc':[{'label':s,'piece':p} for s,p in [('고립','No.1'),('계시','No.1'),('명령','No.2'),('위로','No.3'),('신비','No.3')]],'stages':[]}
