 data['stages'].append({'id':sid,'label':label,'pieceId':'NO01','cueId':f'CUE-N01-0{i+1}','measureRange':m,'printedPages':pg,'narrative':quote(nline),'music':quote(aline),'singing':after('Singing:',a,b),'risk':after('Risk:',a,b),'theology':after('Theology:',a,b),'cueTitle':lines[a-1].split(': ',1)[1],'rawCue':quote(a,b),'normalizedRect':None,'timeRange':None,'mappingStatus':'UNVERIFIED','emotionStatus':'NOT_SEPARATELY_PROVIDED'})
